import { useState, type ComponentProps } from 'react'
import { cn } from '@/lib/utils'
import type { AccentColor } from '@/theme/palettes'
import styles from './Avatar.module.css'

export interface AvatarProps extends ComponentProps<'span'> {
  size?: 'xs' | 'sm' | 'md' | 'lg'
  imageSrc?: string
  /** Who this is. Without it the avatar is decorative and hidden from assistive tech. */
  imageAlt?: string
  /** Shown when there is no image, or it fails to load. One or two letters. */
  initials?: string
  /** Any accent hue. Unset is the neutral gray. */
  color?: AccentColor
  /** `subtle` is a tint of the hue; `solid` is its 600 step (400 in dark). */
  variant?: 'subtle' | 'solid'
}

export function Avatar({
  size = 'sm',
  imageSrc,
  imageAlt,
  initials,
  color,
  variant = 'subtle',
  className,
  ...props
}: AvatarProps) {
  // Keyed by src, so a new imageSrc gets a fresh attempt instead of staying
  // on the fallback from the last one that failed.
  const [failedSrc, setFailedSrc] = useState<string>()
  // An empty string is no image, not a request for the page's own URL.
  const showImage = !!imageSrc && failedSrc !== imageSrc

  return (
    <span
      // The label lives on the container so the image, the initials and the silhouette
      // all announce the same thing: the person, not "S R" or nothing.
      role={imageAlt ? 'img' : undefined}
      aria-label={imageAlt}
      aria-hidden={imageAlt ? undefined : true}
      // The Theme's own palette switch: on the avatar it remaps --primary and
      // its tints to this hue, already measured for contrast.
      data-accent={color}
      className={cn(styles.avatar, styles[size], styles[variant], className)}
      {...props}
    >
      {showImage ? (
        <img
          src={imageSrc}
          alt=""
          className={styles.image}
          onError={() => setFailedSrc(imageSrc)}
        />
      ) : initials ? (
        <span className={styles.initials}>{initials}</span>
      ) : (
        // Drawn to the container's edge, not an icon with a margin: the body
        // runs off the bottom and the circle crops it.
        <svg viewBox="0 0 64 64" className={styles.silhouette}>
          <circle cx="32" cy="26" r="12" />
          <rect x="12" y="42" width="40" height="30" rx="20" />
        </svg>
      )}
    </span>
  )
}

.avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  overflow: hidden;
  /* Always round, whatever the Theme's radius preset: a circle is the shape,
     not a corner setting. */
  border-radius: 9999px;
  font-family: var(--font-sans);
  font-weight: 500;
  line-height: 1;
  user-select: none;
  vertical-align: middle;
}

.xs {
  inline-size: var(--space-6);
  block-size: var(--space-6);
  font-size: var(--text-body-sm);
}

.sm {
  inline-size: var(--space-8);
  block-size: var(--space-8);
  font-size: var(--text-body-sm);
}

.md {
  inline-size: var(--space-10);
  block-size: var(--space-10);
  font-size: var(--text-body);
}

.lg {
  inline-size: var(--space-12);
  block-size: var(--space-12);
  font-size: var(--text-body-lg);
}

.image {
  inline-size: 100%;
  block-size: 100%;
  object-fit: cover;
}

.initials {
  text-transform: uppercase;
}

/* Neutral is the default: no [data-accent], so the gray surface tokens. */
.subtle {
  background: var(--secondary);
  color: var(--secondary-foreground);
}

/* Gray 600 carries a near-white label at 6.5:1 or more on every gray ramp, in
   both appearances, so neutral solid needs no measured token of its own. */
.solid {
  background: var(--gray-600);
  color: var(--gray-50);
}

/* With a hue, the tint and its label are measured per accent by the token
   build; solid is the accent's own fill (600 in light) and label. */
[data-accent].subtle {
  background: var(--primary-subtle);
  color: var(--primary-subtle-text);
}

[data-accent].solid {
  background: var(--primary);
  color: var(--primary-foreground);
}

/* On subtle the silhouette takes the initials' colour, measured on its fill.
   The hue's 600 step would look closer to a portrait but misses 3:1 on the
   warm tints. Neutral subtle is the exception: gray 900 is too heavy for a
   shape this large, and --muted-foreground is measured on the same fill. */
.silhouette {
  inline-size: 100%;
  block-size: 100%;
  fill: currentColor;
}

.subtle:not([data-accent]) .silhouette {
  color: var(--muted-foreground);
}

/* On solid the silhouette is always white, for one consistent look across
   hues. A deliberate a11y trade-off: on the warm hues (orange to lime) it
   falls under the 3:1 a graphic needs. Acceptable because the silhouette
   carries no information: the name is in imageAlt or next to the avatar.
   Initials keep the measured label. */
.solid .silhouette {
  color: var(--gray-50);
}
